# taskrun

Runs the project's tasks, listed in `tasks.json`:

```json
{
  "build": { "script": "scripts/build.js", "args": ["--minify"] }
}
```

```
node bin/taskrun.js build     # runs: node scripts/build.js --minify
node bin/taskrun.js --list
```

Uses [execa](https://github.com/sindresorhus/execa) to run the tasks. Tests: `node --test`.
import { execa } from 'execa';
import { commandFor } from './tasks.js';

// Runs one task with its output going straight to the terminal. Resolves to the task's exit code.
export async function runTask(task, { cwd = process.cwd(), stdio = 'inherit' } = {}) {
  const { file, args } = commandFor(task);
  const result = await execa(file, args, { cwd, stdio, reject: false });
  if (result.failed && result.exitCode === undefined) {
    throw new Error(`could not start the task: ${result.shortMessage}`);
  }
  return result.exitCode;
}
import fs from 'node:fs';
import path from 'node:path';

// tasks.json maps a task name to the Node script it runs:
//   { "build": { "script": "scripts/build.js", "args": ["--minify"] } }
// Paths are relative to the folder that holds tasks.json.

export class TaskError extends Error {}

export function loadTasks(dir = process.cwd()) {
  const file = path.join(dir, 'tasks.json');
  if (!fs.existsSync(file)) throw new TaskError(`no tasks.json in ${dir}`);
  let tasks;
  try {
    tasks = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (err) {
    throw new TaskError(`tasks.json is not valid JSON: ${err.message}`);
  }
  for (const [name, task] of Object.entries(tasks)) validateTask(name, task);
  return tasks;
}

export function validateTask(name, task) {
  if (typeof task !== 'object' || task === null || Array.isArray(task)) {
    throw new TaskError(`task "${name}" must be an object with a "script"`);
  }
  if (typeof task.script !== 'string' || task.script === '') {
    throw new TaskError(`task "${name}" needs a "script"`);
  }
  if (task.args !== undefined && !(Array.isArray(task.args) && task.args.every((a) => typeof a === 'string'))) {
    throw new TaskError(`task "${name}": "args" must be a list of strings`);
  }
}

// The program and arguments a task runs.
export function commandFor(task) {
  return { file: process.execPath, args: [task.script, ...(task.args || [])] };
}
#!/usr/bin/env node
import { loadTasks, TaskError } from '../src/tasks.js';
import { runTask } from '../src/run.js';

const [name] = process.argv.slice(2);

try {
  const tasks = loadTasks();
  if (!name || name === '--list') {
    for (const key of Object.keys(tasks)) console.log(key);
    process.exit(0);
  }
  const task = tasks[name];
  if (!task) {
    console.error(`taskrun: no task "${name}". Tasks: ${Object.keys(tasks).join(', ')}`);
    process.exit(1);
  }
  process.exitCode = await runTask(task);
} catch (err) {
  if (err instanceof TaskError) {
    console.error(`taskrun: ${err.message}`);
    process.exit(1);
  }
  throw err;
}
